from dsl import *

modul("A", "Grundlagen E-Commerce", "Begriffe, Geschäftsmodelle, Artikelnummern, Marktplätze und Technik")

stapel("t01", "A", "Grundbegriffe und Kennzahlen",
    "Die wichtigsten Wörter und Zahlen, z. B. GMV, Warenkorb und Conversion.", [
    S("t01-01", "Was bedeutet B2C?",
      ["Ein Unternehmen verkauft an Privatpersonen (Endverbraucher)", "Ein Unternehmen verkauft an ein anderes Unternehmen", "Privatpersonen verkaufen untereinander", "Ein Marktplatz verkauft an eine Behörde"],
      "B2C heißt Business to Consumer. Der Endkunde auf Zalando oder Amazon ist ein typischer B2C-Kunde.", quelle="Allgemeinwissen"),
    S("t01-02", "Ein Händler bestellt 200 Boxershorts, um sie in seinem Laden weiterzuverkaufen. Welche Art Geschäft ist das?",
      ["B2B", "B2C", "D2C", "C2C"],
      "B2B heißt Business to Business: Ein Unternehmen kauft bei einem anderen Unternehmen. Der Fachhandel ist ein klassisches B2B-Geschäft der Marke.", quelle="Allgemeinwissen"),
    S("t01-03", "Was ist der Unterschied zwischen einem Onlineshop und einem Marktplatz?",
      ["Im Onlineshop verkauft ein Anbieter auf seiner eigenen Seite. Auf einem Marktplatz bieten viele Verkäufer auf einer Plattform an.", "Es gibt keinen Unterschied, beides sind nur andere Wörter", "Ein Marktplatz verkauft nur an Unternehmen, ein Onlineshop nur an Privatpersonen", "Ein Onlineshop ist immer größer als ein Marktplatz"],
      "Beispiel: Eine Marke betreibt einen eigenen Shop, etwa mit Shopify. Amazon, OTTO oder Kaufland sind Marktplätze, auf denen viele Händler, darunter HBOD, verkaufen.", quelle="Allgemeinwissen"),
    S("t01-04", "Bei HBOD gibt es zwei Arten von Kunden. Wer ist der Servicekunde?",
      ["Die Marke bzw. Firma, mit der HBOD den Vertrag hat und die die Ware stellt", "Die Person, die auf Zalando bestellt", "Der Marktplatz, auf dem HBOD verkauft", "Der Paketdienst DHL"],
      "Servicekunde = Marke/Firma mit Vertrag (z. B. eine Wäschemarke). Endkunde = die Person, die online kauft.", quelle="Deine Zusammenfassung (Glossar)"),
    S("t01-05", "Was bedeutet GMV?",
      ["Gross Merchandise Value: der gesamte Warenwert der Verkäufe über eine Plattform in einem Zeitraum", "Gross Margin Value: der Gewinn nach allen Kosten", "Die Auszahlung an die Marke", "Die Zahl der Bestellungen"],
      "GMV ist eine Umsatzgröße und sagt nichts darüber, was am Ende übrig bleibt. Achtung: Ob Retouren schon abgezogen sind, ist nicht einheitlich. Allgemein ist meist der Wert vor Retouren gemeint. Zalando berichtet sein GMV dagegen nach Stornos und Retouren, inklusive Mehrwertsteuer. Frag deshalb immer, welche Definition gemeint ist.", quelle="Allgemeinwissen, Zalando Kennzahlen 2025"),
    Z("t01-06", "Es gibt 100 Bestellungen zu je 50 € brutto, 20 werden komplett zurückgeschickt. Wie hoch ist der Warenwert vor Retouren (GMV nach der üblichen Definition)?", 5000.0,
      "100 × 50 € = 5.000 €. Nach der üblichen Definition zählt das GMV alle Verkäufe, Retouren sind noch nicht abgezogen. Wer GMV wie Zalando nach Retouren rechnet, käme hier auf 4.000 €.", einheit="€", dez=0, quelle="Allgemeinwissen, Zalando Kennzahlen 2025"),
    Z("t01-07", "Gleiches Beispiel: 100 Bestellungen zu je 50 €, 20 kommen zurück. Wie hoch ist der Umsatz nach Retouren?", 4000.0,
      "80 Bestellungen bleiben beim Kunden: 80 × 50 € = 4.000 €. HBOD rechnet in der Abrechnung mit dem Umsatz nach Retouren. Zalandos GMV-Definition entspricht diesem Wert.", einheit="€", dez=0, quelle="Allgemeinwissen"),
    S("t01-08", "Was bedeutet D2C?",
      ["Direct to Consumer: Die Marke verkauft direkt an Endkunden, z. B. über ihren eigenen Onlineshop", "Die Marke verkauft nur an Händler", "Ein Marktplatz verkauft an andere Marktplätze", "Die Ware wird direkt vom Hersteller an HBOD geschickt"],
      "Viele Marken haben einen eigenen D2C-Shop und verkaufen zusätzlich über Händler, Marktplätze oder Dienstleister wie HBOD.", quelle="Allgemeinwissen"),
    S("t01-09", "Was bedeutet Multi-Channel?",
      ["Über viele Kanäle gleichzeitig verkaufen, z. B. mehrere Marktplätze, eigener Shop und Fachhandel", "Nur auf einem Marktplatz verkaufen, dafür in vielen Ländern", "Mehrere Lager gleichzeitig nutzen", "Mit mehreren Paketdiensten versenden"],
      "HBOD beschreibt sich als Multi-Channel-Full-Service-Partner: ein Vertrag, viele Verkaufskanäle.", quelle="Unternehmenspräsentation 2026"),
    S("t01-10", "Was ist mit \"Lost Sales\" gemeint?",
      ["Verkäufe, die verloren gehen, weil die Ware nicht verfügbar war", "Verkäufe, die retourniert wurden", "Verkäufe, für die keine Provision gezahlt wurde", "Verkäufe, die auf dem Versandweg verloren gegangen sind"],
      "Ist ein Artikel ausverkauft, kauft der Kunde woanders. Deshalb plant HBOD 4 bis 6 Wochen Bestandsreichweite.", quelle="Deine Zusammenfassung (Glossar)"),
    S("t01-11", "Was ist in der Kalkulation ein Warenkorb (shopping basket)?",
      ["Alle Artikel einer Bestellung zusammen", "Ein einzelner Artikel", "Alle Bestellungen eines Monats", "Das Lagerfach eines Artikels"],
      "Ein Warenkorb ist eine Bestellung. Bei 1,2 Artikeln pro Warenkorb enthalten 10 Bestellungen im Schnitt 12 Artikel.", quelle="HBOD-Kalkulation (Excel 10/2026)"),
    S("t01-12", "Was beschreibt die Conversion-Rate?",
      ["Den Anteil der Besucher oder Klicks, die am Ende wirklich kaufen", "Den Anteil der Artikel, die zurückgeschickt werden", "Den Wechselkurs zwischen Euro und Franken", "Die Zeit vom Klick bis zur Lieferung"],
      "Beispiel: 1.000 Besucher, 20 Käufe = 2 % Conversion. Viele Klicks ohne Käufe deuten auf ein Problem bei Produktseite, Preis oder Verfügbarkeit hin.", quelle="Allgemeinwissen"),
    M("t01-13", "Ein Artikel hat viele Klicks, aber kaum Käufe. Woran kann das liegen? Kreuze alles Richtige an.",
      ["Die Produktseite überzeugt nicht, z. B. schwache Bilder oder Beschreibung", "Der Preis ist im Vergleich zu hoch", "Gewünschte Größen oder Farben sind nicht verfügbar", "Die Lieferzeit ist zu lang"],
      ["Der Artikel wird zu selten angezeigt", "Die Lagergebühr ist zu hoch"],
      "Viele Klicks heißen: Der Artikel wird gesehen und weckt Interesse. Kauft trotzdem kaum jemand, liegt das Problem meist auf der Produktseite, beim Preis oder bei der Verfügbarkeit. Zu wenig Sichtbarkeit wäre das Gegenteil: wenige Klicks.", quelle="Allgemeinwissen, deine Notizen"),
    W("t01-14", "Zalando berichtet sein GMV nach Abzug von Stornierungen und Retouren.", True,
      "Richtig. Zalando definiert GMV als Wert aller an Kunden verkauften Waren nach Stornos und Retouren, inklusive Mehrwertsteuer. Viele andere rechnen GMV vor Retouren. Deshalb immer nachfragen, welche Definition gemeint ist.", quelle="Zalando Kennzahlen 2025 (corporate.zalando.com)"),
    M("t01-15", "Onlineshop oder Marktplatz: Welche Aussagen stimmen? Kreuze alles Richtige an.",
      ["Auf einem Marktplatz bieten viele Verkäufer auf einer Plattform an", "Im eigenen Onlineshop bestimmt der Anbieter Auftritt und Preise allein", "Auf einem Marktplatz konkurriert man direkt mit anderen Verkäufern, oft um denselben Artikel"],
      ["Für einen Onlineshop braucht man keine Werbung, die Besucher kommen automatisch", "Auf Marktplätzen fallen keine Gebühren an", "Ein Onlineshop ist immer größer als ein Marktplatz"],
      "Marktplätze bringen Reichweite, kosten aber Provision und bringen Konkurrenz um die BuyBox. Im eigenen Shop hat man volle Kontrolle, muss die Besucher aber selbst gewinnen.", quelle="Allgemeinwissen"),
],
    punkte=["GMV (Gross Merchandise Value) ist der Warenwert der Verkäufe über eine Plattform. Er zeigt, wie groß das Geschäft ist, aber nicht, was übrig bleibt.", "Achtung: Allgemein ist GMV meist vor Retouren gemeint, Zalando berichtet es aber nach Stornos und Retouren. Immer fragen, welche Definition gemeint ist.", "Umsatz nach Retouren zählt nur, was die Endkunden behalten. 100 Bestellungen zu 50 €, 20 zurück: 5.000 € vor und 4.000 € nach Retouren. Damit rechnet HBOD in der Abrechnung.", "Ein Warenkorb ist eine Bestellung. Ø 1,2 Artikel pro Bestellung heißt: 10 Bestellungen enthalten zusammen 12 Artikel.", "Conversion-Rate = Käufe ÷ Besucher. Viele Klicks, aber wenige Käufe deuten auf Produktseite, Preis oder Verfügbarkeit.", "B2C: an Endkunden. B2B: an Unternehmen. D2C: die Marke direkt an Endkunden. Bei HBOD ist die Marke der Servicekunde, die Person, die kauft, der Endkunde."],
    merksatz="GMV zeigt, wie viel verkauft wurde. Die Auszahlung zeigt, was bei der Marke ankommt.",
    quelle="Allgemeinwissen, Zalando Kennzahlen 2025, Deine Zusammenfassung (Glossar)")

stapel("t02", "A", "Geschäftsmodelle und Kommission",
    "Wholesale, Vendor, FBA, Dropshipping, Kommission, Konsignation und das HBOD-Modell.", [
    P("t02-01", "Ordne jedem Modell die passende Beschreibung zu.",
      [["Vendor (Wholesale an den Marktplatz)", "Der Marktplatz selbst kauft die Ware ein und bestimmt den Preis"], ["Unabhängiger Händler", "Kauft bei der Marke ein und verkauft auf Marktplätzen zu eigenen Preisen"], ["Fulfillment by Amazon (FBA)", "Die Marke bleibt Verkäufer, Amazon lagert und versendet"], ["Dropshipping", "Verkäufer ohne eigenes Lager, die Ware geht vom Hersteller direkt zum Kunden"], ["HBOD-Modell", "Dienstleister verkauft im eigenen Namen, die Ware gehört bis zum Verkauf der Marke"]],
      "Merke dir die zwei Leitfragen: Wer verkauft an den Endkunden? Wer bestimmt den Preis?", quelle="Deine Zusammenfassung, Einarbeitung"),
    W("t02-02", "Wholesale und Vendor meinen im Alltag dasselbe: Die Plattform kauft die Ware bei der Marke ein.", True,
      "Richtig. Der Kollege hat es so erklärt: Wholesale und Vendor sind das Gleiche, nur anders genannt. Vendor ist meist der Marktplatz, der selbst einkauft (z. B. Amazon Vendor).", quelle="Einarbeitung"),
    S("t02-03", "Was ist für eine Marke das größte Risiko, wenn unabhängige Händler ihre Ware einkaufen und auf Marktplätzen verkaufen?",
      ["Sie verliert die Kontrolle über Preis und Darstellung (Preishoheit)", "Sie muss die Ware zweimal produzieren", "Sie darf die Ware nicht mehr im eigenen Shop verkaufen", "Sie muss den Händlern eine Provision zahlen"],
      "Händler können Preise frei setzen. Verkauft einer billiger, beschweren sich der Fachhandel und andere Händler bei der Marke.", quelle="Einarbeitung"),
    S("t02-04", "Wie nennt man HBODs Rolle gegenüber Marktplätzen und Endkunden?",
      ["Merchant of Record: HBOD ist der Verkäufer im eigenen Namen", "Vendor: HBOD kauft die Ware fest ein", "Marktplatzbetreiber", "Reiner Fulfillment-Dienstleister"],
      "Nach außen ist HBOD der Händler. Für die Marke ist HBOD Dienstleister und \"Enabler\".", quelle="Unternehmenspräsentation 2026, Einarbeitung"),
    M("t02-05", "Was übernimmt HBOD im Full-Service für die Marke? Kreuze alles Richtige an.",
      ["Produktdaten und Produktseiten", "Werbekampagnen auf Marktplätzen", "Versand und Retouren", "Kundenservice für Endkunden", "Zoll- und Umsatzsteuerthemen beim Verkauf"],
      ["Die Ware fest einkaufen und vorab bezahlen", "Die Ware produzieren"],
      "HBOD kauft die Ware nicht vorab und produziert nichts. Die Ware bleibt bis zum Verkauf Eigentum der Marke.", quelle="Unternehmenspräsentation 2026"),
    S("t02-06", "Was ist der Unterschied zwischen reinem Fulfillment und Full-Service?",
      ["Fulfillment ist nur die Logistik. Full-Service umfasst zusätzlich Verkauf, Daten, Marketing, Service und Abrechnung.", "Fulfillment ist teurer als Full-Service", "Full-Service heißt nur Versand innerhalb Deutschlands", "Es gibt keinen Unterschied"],
      "Fulfillment = Wareneingang, Lagerung, Pick & Pack, Versand, Retouren. Bei einem reinen Fulfillment-Dienstleister hat die Marke selbst das Marktplatzkonto. HBOD macht beides.", quelle="Einarbeitung"),
    W("t02-07", "Fulfillment beginnt erst, wenn eine Bestellung eingeht.", False,
      "Falsch. Wareneingang und Lagerung gehören zum Fulfillment und passieren schon vor der Bestellung.", quelle="Allgemeinwissen"),
    S("t02-08", "Was ist der Unterschied zwischen Kommission und Kommissionierung?",
      ["Kommission: Ware wird für jemanden verkauft, das Eigentum bleibt beim Auftraggeber. Kommissionierung: Artikel im Lager für eine Bestellung zusammensuchen.", "Beides bedeutet, Artikel im Lager zu picken", "Kommission ist die Provision, Kommissionierung ist die Rechnung", "Kommissionierung heißt, Ware auf Kommission einzukaufen"],
      "Die Wörter klingen ähnlich, meinen aber ganz Verschiedenes. Kommissionierung = Picken.", quelle="Allgemeinwissen"),
    S("t02-09", "Was ist ein Konsignationslager?",
      ["Die Ware liegt beim Händler oder Dienstleister, gehört aber bis zum Verkauf dem Lieferanten", "Ein Lager, das nur Retouren aufnimmt", "Ein Lager im Ausland", "Ein Lager, in dem nur verkaufte Ware liegt"],
      "Konsignation heißt: Die Ware liegt schon beim Händler oder Dienstleister, gehört aber bis zum Verkauf oder zur Entnahme weiter dem Lieferanten. So ist es auch bei HBOD: Die Ware liegt in Mülheim und bleibt bis zum Verkauf Eigentum der Marke.", quelle="Allgemeinwissen, Unternehmenspräsentation 2026", hinweis="Der Begriff „umgekehrtes Konsignationslager“ wird nicht einheitlich verwendet. Im Zweifel nachfragen, was gemeint ist."),
    S("t02-11", "Was ist für die Marke der Vorteil von Wholesale gegenüber dem HBOD-Modell?",
      ["Die Ware ist verkauft und das Geld kommt nach dem Zahlungsziel, unabhängig davon, ob Endkunden kaufen", "Sie behält die volle Kontrolle über den Endkundenpreis", "Sie zahlt keine Logistik und hat trotzdem alle Daten", "Retouren bekommt sie immer erstattet"],
      "Wholesale bringt Cashflow und weniger Risiko. Dafür verliert die Marke Kontrolle über Preis und Darstellung.", quelle="Einarbeitung"),
    S("t02-12", "Warum empfehlen Kollegen oft einen Mix aus Wholesale-Händlern und HBOD?",
      ["Wholesale bringt Cashflow, HBOD bedient den übrigen Markt mit Kontrolle über Preis und Auftritt", "Weil HBOD sonst keine Ware bekommt", "Weil Wholesale-Händler HBOD bezahlen", "Weil ein Mix gesetzlich vorgeschrieben ist"],
      "Typisch sind drei bis vier Onlinehändler, die wirklich einkaufen, plus HBOD. HBOD ergänzt das bestehende Geschäft.", quelle="Einarbeitung"),
    S("t02-13", "Was bedeutet \"Inhouse\"?",
      ["Die Marke macht alles selbst: Marketing, Lager, Versand, Retouren, Marktplatzkonten", "Die Marke lagert bei HBOD", "Die Marke verkauft nur im eigenen Laden", "Die Marke kauft bei HBOD ein"],
      "Inhouse heißt volle Kontrolle, aber auch voller Aufwand und hoher Ressourcenbedarf.", quelle="Deine Zusammenfassung"),
    S("t02-14", "Auf OTTO steht bei einem Markenartikel als Verkäufer ein großes Versandhaus, nicht die Marke. Was bedeutet das?",
      ["Ein anderes Unternehmen verkauft die Ware. Wie es an die Ware kommt (Einkauf, Lizenz oder eigene Marke), muss man klären.", "Die Marke gehört automatisch zu OTTO", "Das Versandhaus ist nur der Paketdienst von OTTO", "Die Marke verkauft dort selbst unter anderem Namen"],
      "Die Verkäuferinfo auf OTTO oder Amazon zeigt, wer verkauft. Wie der Verkäufer an die Ware kommt, steht dort nicht. Das klärst du im Gespräch mit der Marke, z. B.: \"Wer vertreibt Ihre Ware bei OTTO?\"", quelle="Allgemeinwissen"),
    S("t02-15", "Eine Sportmarke erlaubt einem Wäschehersteller, Unterwäsche unter ihrem Markennamen herzustellen und zu verkaufen. Wie nennt man dieses Modell?",
      ["Lizenz: Die Sportmarke erlaubt dem Hersteller, ihren Namen für eine Produktkategorie zu nutzen", "Wholesale: Der Hersteller kauft fertige Ware bei der Sportmarke ein", "Dropshipping: Die Sportmarke verschickt direkt an die Kunden des Herstellers", "Vendor: Die Sportmarke verkauft an einen Marktplatz"],
      "Der Lizenznehmer lässt die Ware herstellen und verkauft sie. Der Lizenzgeber kann mitbestimmen, wo verkauft wird, z. B. in welchen Ländern oder auf welchen Marktplätzen. Deshalb spielen Lizenzen bei den Kanalfreigaben eine Rolle. Vertragspartner ist dann die Firma mit der Lizenz, nicht die Marke selbst.", quelle="Allgemeinwissen"),
    S("t02-16", "Eine Marke lässt ihre Ware von einem Händler verkaufen. Der Händler verkauft im eigenen Namen, aber auf Rechnung der Marke. Wer ist der Kommittent?",
      ["Die Marke, also die Auftraggeberin, auf deren Rechnung verkauft wird", "Der Händler, der die Ware verkauft", "Der Endkunde, der die Ware kauft", "Der Marktplatz, auf dem verkauft wird"],
      "Beim Kommissionsgeschäft gibt es zwei Rollen: Der Kommittent ist der Auftraggeber, auf dessen Rechnung verkauft wird. Der Kommissionär verkauft im eigenen Namen. Merkhilfe: Der Kommittent gibt die Ware in Kommission.", quelle="§ 383 HGB, deine Notizen", hinweis="Rechtsgrundsatz zum Verstehen, keine Rechtsberatung."),
    M("t02-17", "Wann ist jemand nach dem HGB Kommissionär? Kreuze alle Bedingungen an.",
      ["Er kauft oder verkauft Waren (oder Wertpapiere) für einen anderen", "Er handelt im eigenen Namen", "Er handelt auf fremde Rechnung, also auf Rechnung des Kommittenten", "Er macht das gewerbsmäßig, also als Teil seines Geschäfts"],
      ["Er handelt im Namen des Auftraggebers", "Ihm gehört die Ware schon vorher", "Es braucht zwingend einen schriftlichen Vertrag"],
      "So steht es in § 383 HGB: Kommissionär ist, wer es gewerbsmäßig übernimmt, Waren oder Wertpapiere für Rechnung eines anderen in eigenem Namen zu kaufen oder zu verkaufen. Wer im Namen des Auftraggebers handelt, ist dagegen Vertreter, z. B. Handelsvertreter.", quelle="§ 383 HGB, deine Notizen", hinweis="Rechtsgrundsatz zum Verstehen, keine Rechtsberatung."),
    S("t02-18", "Was ist ein Gelegenheitskommissionär?",
      ["Ein Kaufmann, der nicht gewerbsmäßig Kommissionär ist, aber in seinem Betrieb einzeln ein Kommissionsgeschäft übernimmt. Dann gelten die Kommissionsregeln trotzdem.", "Ein Kommissionär, der nur in der Weihnachtszeit arbeitet", "Ein Endkunde, der gelegentlich Ware zurückschickt", "Ein Händler, der Ware nur im Namen des Herstellers verkauft"],
      "Das regelt § 406 HGB: Die Regeln für Kommissionsgeschäfte gelten auch, wenn ein Kaufmann, der kein Kommissionär ist, im Betrieb seines Handelsgewerbes ein solches Geschäft übernimmt. Entscheidend ist also die Art des Geschäfts: im eigenen Namen, auf fremde Rechnung.", quelle="§ 406 HGB, deine Notizen", hinweis="Rechtsgrundsatz zum Verstehen, keine Rechtsberatung."),
    S("t02-19", "Was ist mit „Blitz-Eigentum“ gemeint?",
      ["Ein Händler wird nur für einen kurzen, rechtlichen Moment Eigentümer der Ware, bevor sie an den Endkunden weitergeht", "Ware, die besonders schnell geliefert wird", "Ware, die in einer Blitz-Aktion günstiger verkauft wird", "Ware gehört dem Händler, sobald sie in seinem Lager ankommt"],
      "Gemeint ist ein Durchgangserwerb für eine „juristische Sekunde“. Das passt zum HBOD-Modell: Die Ware gehört bis zum Verkauf der Marke, HBOD verkauft aber im eigenen Namen an den Endkunden und ist dafür nur ganz kurz Eigentümer.", quelle="Deine Notizen, Allgemeinwissen", hinweis="Umgangssprachlicher Begriff, kein Gesetzesbegriff. Wie das im HBOD-Modell genau geregelt ist, intern bestätigen."),
    S("t02-20", "Was ist der Unterschied zwischen Logistik und Fulfillment?",
      ["Logistik bewegt und lagert Ware. Fulfillment wickelt die ganze Bestellung ab: Logistik plus Picken und Packen je Bestellung, Retourenabwicklung und oft Kundenservice und Abrechnung.", "Es gibt keinen Unterschied, beides heißt Versand", "Fulfillment ist nur der Transport zum Kunden, Logistik umfasst alles andere", "Logistik gibt es nur im B2B, Fulfillment nur im B2C"],
      "Logistik ist der Oberbegriff für Transport, Lagerung, Wareneingang, Versand und Rücktransport. Fulfillment hängt an der Bestellung und umfasst alles, was dazugehört. Full-Service wie bei HBOD geht noch weiter: Verkauf, Produktdaten, Marketing und Abrechnung kommen dazu.", quelle="Deine Notizen, Allgemeinwissen"),
],
    punkte=["HBOD verkauft im eigenen Namen und auf eigene Rechnung (Merchant of Record). Nach außen ist HBOD der Händler, für die Marke ein Dienstleister.", "Die Ware liegt in Mülheim, gehört aber bis zum Verkauf der Marke (Konsignation). HBOD bindet kein eigenes Kapital in Ware (asset-light).", "Kommission: Der Kommissionär verkauft im eigenen Namen auf Rechnung des Kommittenten (§ 383 HGB). Macht ein Kaufmann das nur gelegentlich, gelten die Regeln trotzdem (Gelegenheitskommissionär, § 406 HGB).", "Wholesale bzw. Vendor: Die Plattform oder ein Händler kauft fest ein. Vorteil für die Marke: Cashflow und weniger Risiko. Nachteil: kaum Kontrolle über Preis und Darstellung.", "Logistik bewegt und lagert Ware. Fulfillment wickelt die ganze Bestellung ab. Full-Service umfasst zusätzlich Verkauf, Daten, Marketing, Service und Abrechnung. HBOD macht alles.", "Oft ideal ist ein Mix: einige Händler, die fest einkaufen, plus HBOD für den übrigen Markt. HBOD ergänzt, statt zu ersetzen."],
    merksatz="Zwei Leitfragen: Wer verkauft an den Endkunden? Wer bestimmt den Preis?",
    quelle="Unternehmenspräsentation 2026, §§ 383 und 406 HGB, Einarbeitung",
    hinweis="Rechtsgrundsatz zum Verstehen, keine Rechtsberatung.")

stapel("t03", "A", "Artikel, Nummern und Stammdaten",
    "EAN, SKU, ASIN, Vater- und Kindartikel, Bundles und Stammdaten.", [
    S("t03-01", "Was ist eine EAN?",
      ["Eine weltweit eindeutige Artikelnummer, meist 13-stellig, die als Barcode auf dem Artikel steht", "Eine interne Nummer, die jede Firma frei vergibt", "Amazons eigene Produktnummer", "Die Lagerplatznummer bei HBOD"],
      "EANs werden über GS1 vergeben. Jede Variante (Farbe, Größe) hat eine eigene EAN.", quelle="Allgemeinwissen, Deine Zusammenfassung"),
    W("t03-02", "GTIN und EAN meinen im Alltag dasselbe.", True,
      "Richtig. Genau genommen ist GTIN der Oberbegriff, und die 13-stellige EAN ist eine GTIN-13. Marktplätze schreiben oft \"GTIN/EAN\".", quelle="Deine Zusammenfassung"),
    S("t03-03", "Was ist eine SKU?",
      ["Eine interne Artikelnummer, die ein Unternehmen selbst vergibt", "Eine weltweit eindeutige Nummer von GS1", "Die Nummer einer Bestellung", "Die Steuernummer der Marke"],
      "Die SKU gilt nur im eigenen System. SKU und EAN sind zwei verschiedene Nummern für denselben Artikel.", quelle="Deine Zusammenfassung"),
    S("t03-04", "Was ist eine ASIN?",
      ["Amazons eigene Nummer für eine Produktseite, die es nur auf Amazon gibt", "Ein anderes Wort für EAN", "Die Nummer des Amazon-Lagers", "Eine Steuernummer für Amazon-Händler"],
      "Bei Amazon gibt man die EAN an, und Amazon ordnet sie einer ASIN zu oder legt eine neue an.", quelle="Allgemeinwissen"),
    R("t03-05", "Bringe die Artikelebenen in die richtige Reihenfolge, von oben (allgemein) nach unten (konkret).",
      ["Vaterartikel (alle Farben und Größen eines Modells)", "Farbartikel (eine Farbe, alle Größen)", "Kindartikel (eine Farbe in einer Größe)"],
      "Der Kindartikel ist die verkaufbare Einheit. Er hat eine SKU und eine EAN.", quelle="Deine Zusammenfassung"),
    S("t03-06", "Ein Hemd in Blau, Größe M ist ein …",
      ["Kindartikel (Kindelement)", "Vaterartikel", "Farbartikel", "Bundle"],
      "Eine Farbe in einer Größe = Kindartikel. In Warenwirtschaftssystemen heißt das oft Kindelement.", quelle="Deine Zusammenfassung"),
    S("t03-07", "Was ist der Unterschied zwischen Multipack und Bundle?",
      ["Multipack: mehrere gleiche Artikel. Bundle: verschiedene Artikel zusammen.", "Multipack: verschiedene Artikel. Bundle: mehrere gleiche Artikel.", "Beides ist dasselbe", "Ein Bundle ist immer billiger als ein Multipack"],
      "Beispiel: 3 schwarze Boxershorts = Multipack. Boxershorts und Socken zusammen = Bundle.", quelle="Deine Zusammenfassung (Glossar)"),
    W("t03-08", "Wenn HBOD ein Bundle oder Multipack anlegt, braucht es eine neue EAN.", True,
      "Richtig. Ein Bundle ist ein neuer Artikel und braucht eine eigene Nummer. HBOD baut Bundles virtuell aus Einzelartikeln.", quelle="Deine Zusammenfassung, Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t03-09", "Warum braucht HBOD für Bundles auf Amazon freie EANs von der Marke?",
      ["Weil bei Amazon der Nummernkreis der EAN zur Marke gehören muss", "Weil Amazon keine Bundles erlaubt", "Weil HBOD keine eigenen EANs kaufen darf", "Weil EANs bei Amazon nach einem Jahr ablaufen"],
      "Die Marke stellt freie Nummern aus ihrem eigenen Nummernkreis bereit, die HBOD den Bundles zuordnet. Vorher zusammenpacken muss niemand etwas.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t03-10", "Was ist eine Stückliste?",
      ["Ein interner Begriff für mehrere Artikel im System, die zusammen als ein Artikel verkauft werden", "Die Liste aller Artikel einer Lieferung", "Die Inventurliste am Jahresende", "Eine Liste der Retouren"],
      "Über Stücklisten entstehen in der Warenwirtschaft die virtuellen Bundles und Multipacks.", quelle="Deine Zusammenfassung (Glossar)"),
    S("t03-11", "Was ist ein Packshot (Hollow Man)?",
      ["Ein Produktfoto auf weißem Hintergrund, bei Kleidung auf einer unsichtbaren Puppe", "Ein Foto vom gepackten Paket", "Ein Modelfoto im Freien", "Ein Video vom Auspacken"],
      "HBOD kann Hollow-Man-Packshots für 19,95 € je Artikel erstellen. Modelfotos muss die Marke liefern.", quelle="Preisliste 10/2026, Deine Zusammenfassung"),
    S("t03-12", "Was ist ein NOS-Artikel?",
      ["Never out of stock: ein Basisartikel, der dauerhaft verfügbar sein soll", "Ein Artikel, der nicht mehr verkauft wird", "Ein Artikel ohne EAN", "Ein Saisonartikel"],
      "NOS-Artikel sind Dauerläufer, z. B. schwarze Basic-Boxershorts. Saisonware hat dagegen nur ein kurzes Verkaufsfenster.", quelle="Allgemeinwissen, Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t03-13", "Was erwartet HBOD von einer \"EAN-Liste\" der Marke?",
      ["Ein ausgefülltes Stammdatenblatt mit allen Informationen zu jedem Artikel", "Nur eine Aufzählung der EAN-Nummern", "Die Bilder der Artikel", "Die Preisliste der Marke für den Fachhandel"],
      "Eine reine Nummernliste reicht nicht. In Ausnahmefällen hilft das Marktplatzmanagement, solange Grundinformationen da sind.", quelle="Deine Zusammenfassung"),
    M("t03-14", "Welche Angaben gehören in die Artikelstammdaten? Kreuze alles Richtige an.",
      ["EAN je Größe und Farbe", "Artikelname", "Farbe und Größe", "Material bzw. Zusammensetzung", "UVP", "Maße und Gewicht"],
      ["Bankverbindung der Marke", "Passwort für den Marktplatz"],
      "Maße und Gewicht braucht HBOD für Lager- und Versandkosten. Bankdaten und Passwörter gehören nicht in Stammdaten.", quelle="Deine Zusammenfassung, Brand Info"),
    P("t03-15", "Ordne die GTIN-Arten zu.",
      [["GTIN-13", "EAN mit 13 Stellen, in Europa und weltweit üblich"], ["GTIN-12", "UPC mit 12 Stellen, vor allem in den USA und Kanada"], ["GTIN-8", "kurze Nummer für sehr kleine Artikel"], ["GTIN-14", "für Umkartons und Logistikeinheiten"]],
      "Alle vier gehören zur GTIN-Familie von GS1. An der Kasse und im Onlinehandel zählen GTIN-8, -12 und -13. Die GTIN-14 kennzeichnet Verpackungseinheiten wie Kartons und wird an der Kasse nicht gescannt.", quelle="GS1, deine Notizen"),
],
    punkte=["EAN: weltweit eindeutige Nummer, meist 13-stellig und als Barcode auf dem Artikel, je Farbe und Größe eine eigene. GTIN ist der Oberbegriff (GTIN-8, -12, -13, -14).", "SKU: interne Nummer. ASIN: Amazons eigene Nummer für eine Produktseite.", "Artikelebenen: Vaterartikel (das Modell), Farbartikel, Kindartikel (eine Farbe in einer Größe). Der Kindartikel ist die verkaufbare Einheit mit SKU und EAN.", "Multipack = mehrere gleiche Artikel, Bundle = verschiedene Artikel. Beide brauchen eine neue EAN. Bei Amazon muss der Nummernkreis zur Marke gehören.", "Stammdaten: EAN je Variante, Artikelname, Farbe und Größe, Material, UVP, Maße und Gewicht. Eine reine Nummernliste reicht nicht."],
    merksatz="Eine Farbe in einer Größe = ein Kindartikel = eine EAN.",
    quelle="Deine Zusammenfassung (Glossar), GS1, Allgemeinwissen")

stapel("t04", "A", "Marktplätze verstehen",
    "Wie Marktplätze ticken: Suchmaschine oder Katalog, BuyBox, SLAs, Länder und Freigaben.", [
    S("t04-01", "Was unterscheidet Amazon und OTTO von Zalando und ABOUT YOU?",
      ["Amazon und OTTO funktionieren wie eine Suchmaschine, Zalando und ABOUT YOU eher wie ein Katalog zum Stöbern", "Amazon und OTTO verkaufen nur Elektronik", "Zalando und ABOUT YOU haben keine Retouren", "Auf Amazon und OTTO gibt es keine Konkurrenz"],
      "Auf Amazon weiß der Kunde meist, was er will. Auf Zalando lässt er sich inspirieren und bestellt öfter zur Auswahl.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t04-02", "Warum hat Zalando viel mehr Retouren als Amazon?",
      ["Kostenlose Retoure und Auswahlbestellungen in mehreren Größen und Farben, über Jahre so gelernt", "Weil Zalando schlechtere Ware verkauft", "Weil Amazon Retouren verbietet", "Weil Zalando nur ins Ausland liefert"],
      "Bei Amazon muss der Kunde das Retourenlabel selbst erzeugen. Das ist eine kleine Hürde, die Retouren senkt.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    P("t04-03", "Ordne die Retourenquoten zu (Richtwerte aus den Gesprächen).",
      [["Amazon", "niedrig, etwa 2 bis 10 %"], ["Zalando", "hoch, etwa 20 bis 30 %"], ["BHs und Badehosen", "sehr hoch, teils über 40 %"]],
      "Die Quote hängt stark von Marktplatz und Produkt ab. Deshalb rechnet das MPE je Marktplatz und Land mit eigenen Quoten.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Richtwerte aus Gesprächen. Intern bestätigen."),
    S("t04-04", "Was ist die BuyBox?",
      ["Das Feld \"In den Warenkorb\". Wer die BuyBox hat, bekommt den Verkauf.", "Eine Verpackung für Retouren", "Ein Rabatt-Event auf Amazon", "Die Kiste im Lager, in der Bestellungen gesammelt werden"],
      "Bieten mehrere Händler denselben Artikel an, bekommt nur einer die BuyBox.", quelle="Deine Zusammenfassung (Glossar)"),
    M("t04-05", "Wovon hängt ab, wer die BuyBox bekommt? Kreuze alles Richtige an.",
      ["Preis", "Lieferzeit und Verfügbarkeit", "Verkäuferqualität (Bewertungen, Account Health, Retourenquote)", "Prime-Status bei Amazon"],
      ["Größe des Firmenlogos", "Anzahl der Mitarbeiter des Händlers"],
      "Die BuyBox orientiert sich an den SLAs und der Verkäuferleistung.", quelle="Deine Zusammenfassung"),
    S("t04-06", "Was ist ein SLA?",
      ["Service Level Agreement: Vorgaben des Marktplatzes zu Versand, Lieferzeit und Stornos, die der Verkäufer einhalten muss", "Ein Rabatt für große Händler", "Ein Vertrag zwischen Marke und HBOD über die Provision", "Ein Werbeformat"],
      "Wer SLAs verletzt, verliert z. B. Prime oder wird gesperrt.", quelle="Einarbeitung"),
    S("t04-07", "Was bedeutet: \"Eine Anbindung ist keine Markenfreigabe\"?",
      ["HBOD kann technisch angebunden sein, aber der Marktplatz muss die Marke trotzdem zulassen", "Jede Marke darf automatisch auf jeden Marktplatz, auf dem HBOD verkauft", "Die Marke braucht eine eigene Schnittstelle", "Der Marktplatz muss HBOD erst freigeben"],
      "Zalando und Galeries Lafayette zum Beispiel sind kuratiert: Sie entscheiden selbst, welche Marken sie aufnehmen. Die Chancen lassen sich deshalb nicht sicher zusagen.", quelle="Allgemeinwissen, Einarbeitung"),
    P("t04-08", "Ordne Marktplatz und Rolle zu.",
      [["bol", "stärkster Marktplatz in den Niederlanden und Belgien"], ["Galaxus", "sehr wichtiger Marktplatz in der Schweiz"], ["Allegro", "größter Marktplatz in Polen und Mittelosteuropa"], ["Galeries Lafayette", "französisch, stark kuratiert, vor allem große und französische Marken"], ["Limango / Veepee", "Shopping-Club mit zeitlich begrenzten Aktionen"]],
      "Diese Zuordnung hilft dir bei der Frage \"Welche Marktplätze empfehlt ihr?\".", quelle="Allgemeinwissen"),
    S("t04-09", "Wofür werden Shopping-Clubs wie Limango oft genutzt?",
      ["Als Abverkaufskanal für Aktionen und Restbestände", "Als Hauptkanal für neue Kollektionen zum vollen Preis", "Nur für B2B-Kunden", "Für den Verkauf in die Schweiz"],
      "Marktplätze haben unterschiedliche Rollen: Limango eher für Abverkauf, Amazon für Suche, Zalando für Inspiration.", quelle="Deine Notizen"),
    W("t04-10", "GALERIA und Galeries Lafayette sind derselbe Marktplatz.", False,
      "Falsch. GALERIA ist das deutsche Warenhaus, Galeries Lafayette ist französisch. Beide getrennt betrachten.", quelle="Allgemeinwissen"),
    S("t04-11", "Was ist zDirect?",
      ["Das Partnerportal von Zalando, in dem man z. B. Kennzahlen wie die Retourenquote sieht", "Eine Middleware für Amazon", "Ein Werbeformat von Zalando", "Das Kassensystem von HBOD"],
      "In deinen Notizen steht: In zDirect siehst du die Retourenquote bei Zalando.", quelle="Deine Notizen", hinweis="Funktionsumfang bei Bedarf im Team zeigen lassen"),
    S("t04-12", "Was ist ein BrandHome bei Zalando?",
      ["Eine eigene Markenseite mit Kollektionen, Bildern und Videos, der Nutzer folgen können", "Das Lager einer Marke", "Ein Rabattcode", "Der Firmensitz von Zalando"],
      "Follower bekommen Push-Nachrichten und sehen die Produkte eher.", quelle="Einarbeitung"),
    M("t04-13", "Warum ist Allegro für viele westliche Marken schwierig? Kreuze alles Richtige an.",
      ["Inhalte und Service müssen auf Polnisch sein", "Der Markt ist reif und hart umkämpft", "Oft bieten Händler die Marke dort schon an", "Verkäufer werden streng geprüft (Verifizierung, KYC)"],
      ["Allegro lässt grundsätzlich keine ausländischen Verkäufer zu", "In Polen wird kaum online eingekauft"],
      "Laut einem Branchen-Newsletter erwartet Allegro in diesem Jahr rund 19 Mrd. € Umsatz und ist damit einer der größten Marktplätze Europas.", quelle="Branchen-Newsletter Marketplace Universe, Recherche"),
],
    punkte=["Amazon und OTTO funktionieren eher wie eine Suchmaschine, Zalando und ABOUT YOU wie ein Katalog zum Stöbern.", "Die BuyBox bekommt nur ein Verkäufer. Es zählen Preis, Lieferzeit, Verfügbarkeit, Verkäuferqualität und bei Amazon Prime.", "SLAs sind die Vorgaben eines Marktplatzes zu Versand, Lieferzeit und Stornos. Wer sie verletzt, riskiert Sperren.", "Rollen: bol für Niederlande und Belgien, Galaxus für die Schweiz, Allegro für Polen, Galeries Lafayette französisch und kuratiert, Limango und Veepee als Shopping-Clubs für den Abverkauf.", "Eine technische Anbindung ist keine Markenfreigabe. Kuratierte Marktplätze entscheiden selbst, welche Marken sie aufnehmen."],
    merksatz="Erst den Marktplatz verstehen, dann die Marke empfehlen.",
    quelle="Allgemeinwissen, Einarbeitung")

stapel("t05", "A", "Anbindung und Tools",
    "Wie Daten zum Marktplatz kommen, wie man Fehler sucht und was das MPE kann.", [
    S("t05-02", "Was ist eine Middleware?",
      ["Ein Zwischenprogramm, das die Daten eines Verkäufers verarbeitet und an viele Marktplätze weitergibt", "Ein Lagerverwaltungsprogramm", "Eine Werbeagentur", "Ein Paketdienst"],
      "Middleware ist der Modellbegriff: ein Programm zwischen dem eigenen System und vielen Marktplätzen, das die Daten in deren Formate übersetzt.", quelle="Einarbeitung"),
    S("t05-03", "Was ist ein Nachteil von Middleware?",
      ["Sie kostet Transaktionsgebühren und hat eigene Laufzeiten für Updates", "Sie funktioniert nur in Deutschland", "Sie kann keine Bilder übertragen", "Sie ist kostenlos, aber langsam"],
      "Deshalb lohnt sich bei großem Volumen manchmal eine Direktanbindung.", quelle="Einarbeitung"),
    S("t05-04", "Warum ist eine Direktanbindung nicht automatisch besser?",
      ["Sie ist teuer: viel IT-Aufwand, Pflege der Schnittstelle, Server, und bei Ausfall steht alles", "Weil Marktplätze keine Direktanbindungen erlauben", "Weil dann keine Bilder angezeigt werden", "Weil sie gegen die SLAs verstößt"],
      "Der Kollege nannte das eine Make-or-Buy-Entscheidung der IT.", quelle="Einarbeitung"),
    R("t05-05", "Ein Artikel wird falsch angezeigt. In welcher Reihenfolge sucht man den Fehler?",
      ["Eigene Daten in der Warenwirtschaft prüfen", "Übertragung über die Middleware prüfen", "Darstellung beim Marktplatz prüfen"],
      "Die Leitfrage lautet: Wer ist für was verantwortlich, welches Programm hängt dazwischen?", quelle="Einarbeitung"),
    S("t05-08", "Wofür steht MPE?",
      ["Marketplace Profit Engine", "Marktpreisempfehlung", "Monthly Payout Estimate", "Multi Product Export"],
      "Das MPE ist HBODs internes Preis- und Profitabilitätstool.", quelle="Unternehmenspräsentation 2026, Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    W("t05-09", "Das MPE ist die Marktpreisempfehlung der Marke, also dasselbe wie die UVP.", False,
      "Falsch. Die UVP legt die Marke fest. Das MPE ist HBODs Rechentool, das Preise je Marktplatz berechnet. MPE-Preis und UVP können weit auseinanderliegen.", quelle="Einarbeitungs-Chat", hinweis="Aus dem Einarbeitungs-Chat. Intern bestätigen."),
    M("t05-10", "Was kann das MPE? Kreuze alles Richtige an.",
      ["Preis je Marktplatz und Land berechnen", "Rückwärts rechnen: von der Zielauszahlung zum nötigen Preis", "Ein Rot-Grün-Signal geben, ob sich ein Artikel lohnt", "Preisunter- und Preisobergrenzen berücksichtigen"],
      ["Kunden können es heute selbst über eine Oberfläche bedienen", "Es garantiert jedem Artikel einen Verkauf"],
      "So lässt sich je Marktplatz und Land zeigen, ob sich ein Artikel lohnt und welcher Preis dafür nötig ist.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t05-12", "Was sind Kanalfreigaben?",
      ["Die Marke legt fest, auf welchen Marktplätzen und in welchen Ländern HBOD verkaufen darf", "Die Freigabe von DHL für neue Länder", "Ein Rabatt für neue Kanäle", "Die Erlaubnis des Finanzamts"],
      "Gründe können Lizenzen oder politische Gründe sein, z. B. wenn der Lizenzgeber bestimmte Länder ausschließt.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
],
    punkte=["Anbindung an Marktplätze geht direkt über eine Schnittstelle (API) oder über eine Middleware, die die Daten an viele Marktplätze verteilt.", "Middleware kostet Transaktionsgebühren und hat eigene Laufzeiten, eine Direktanbindung kostet viel IT-Aufwand. Das ist eine Make-or-Buy-Entscheidung.", "Wird ein Artikel falsch angezeigt: erst die eigenen Daten prüfen, dann die Übertragung, dann die Darstellung beim Marktplatz.", "Das MPE (Marketplace Profit Engine) ist HBODs Preis- und Profitabilitätstool. Es ist nicht dasselbe wie die UVP.", "Kanalfreigaben: Die Marke legt fest, auf welchen Marktplätzen und in welchen Ländern HBOD verkaufen darf."],
    merksatz="Wer ist für was verantwortlich, und welches Programm hängt dazwischen?",
    quelle="Einarbeitung, Unternehmenspräsentation 2026")
